INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'todas', 'Gabarito de altura máxima contado a partir de 6 m do perfil natural do terreno (antes: a partir do primeiro pavimento aflorado).', 'LEI_18081_2024', 'art. 38 (art. 68 da 16.402), redação da Lei 18.177/2024 art. 5º');
INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'ZEU,ZEUP,ZEM,ZEMP', 'Na faixa de 20 m junto a vilas e ruas sem saída: gabarito máximo de 28 m nessas zonas e 15 m nas demais, quando o da zona não for mais restritivo.', 'LEI_18081_2024', 'art. 35 (art. 64 da 16.402)');
INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'todas', 'Taxa de ocupação calculada considerando a projeção do subsolo aflorado.', 'LEI_18081_2024', 'art. 33 (art. 61 da 16.402) §6º');
INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'todas', 'Lote acima da área máxima da zona com edificação existente: nova taxa de ocupação fixada entre 50% e 70%.', 'LEI_18081_2024', 'art. 26 (art. 42-C da 16.402)');
INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'ZEU,ZEUa,ZEUP,ZEUPa,ZEM,ZEMP', 'Passeio de 5 m; recuo de frente dispensado quando o passeio já tem 5 m ou há doação de área.', 'LEI_18081_2024', 'art. 37 (art. 67 da 16.402)');
INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'todas', 'Sem recuo mínimo de frente quando ao menos 50% da face de quadra está construída no alinhamento.', 'LEI_18081_2024', 'art. 39 (art. 69 da 16.402)');
INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'ZDE-2,ZPI-1,ZPI-2', 'Dispensa de recuos laterais e de fundo quando inviabilizariam a taxa de ocupação.', 'LEI_18081_2024', 'art. 36 (art. 66 da 16.402)');
INSERT INTO regras (cidade, zonas, texto, norma_id, dispositivo) VALUES ('São Paulo', 'todas', 'Novo Mapa 1 (perímetros das zonas) substitui o da Lei 18.081; vários lotes mudaram de zona (ex.: ZM->ZEU, ZC->ZEU, ZDE->ZEM, ZC->ZEIS-5). A zona do lote deve vir do mapa de 2024.', 'LEI_18177_2024', 'art. 8º');
